const { randomUUID, createHmac } = require('crypto');
const body = {
  user_token: $env.JOSHO_HR_USER_TOKEN,
  subject: $json.subject || '',
  from: ($json.from && $json.from.value && $json.from.value[0] && $json.from.value[0].address) || '',
  classification: '',
  received_at: new Date($json.internalDate ? Number($json.internalDate) : Date.now()).toISOString(),
  body_preview: ($json.snippet || '').slice(0, 500)
};
const raw = JSON.stringify(body);
const signature = 'sha256=' + createHmac('sha256', $env.JOSHO_HR_HMAC).update(raw).digest('hex');
return [{
  json: { body, raw },
  binary: {},
  headers: {
    'Content-Type': 'application/json',
    'X-JoshoHR-Contract': 'v1',
    'X-JoshoHR-Signature': signature,
    'Idempotency-Key': randomUUID()
  }
}];
